def article_search(title: str) -> str:
    return "https://en.wikipedia.org/w/index.php?search=" + quote(title)


def gfg_search(title: str) -> str:
    return "https://www.geeksforgeeks.org/?s=" + quote(title)


def generic_course_frame(course_name: str, topic_name: str, category: str):
    """Careful, useful study framing for branch subjects outside the 25 shared courses."""
    discipline = f"{course_name} belongs to the {category or 'engineering'} curriculum."
    return (
        f"{discipline} Study {topic_name} by identifying its terms, assumptions, representations, and the relationships between them.",
        "Definitions and notation, components or cases, governing rules, and checks that validate a result",
        f"For a {topic_name.lower()} problem in {course_name}, write down the known values and constraints, choose the governing concept, work through a small case, and check units, boundary conditions, or expected behavior.",
        "Use the model only within its stated assumptions; check dimensions, boundary cases, safety constraints, and whether the chosen simplification fits the real system.",
        "",
        "",
    )

def build():
    topics = list(csv.DictReader((DATA / "topics.csv").open(encoding="utf-8-sig", newline="")))
    questions = list(csv.DictReader((DATA / "practice_question_bank.csv").open(encoding="utf-8-sig", newline="")))
    core_by_name = {row["topic_name"]: row for row in topics}
    catalog = {row["course_code"]: row for row in csv.DictReader((DATA / "courses.csv").open(encoding="utf-8-sig", newline=""))}
    branch_rows = list(csv.DictReader((DATA / "branch_curriculum.csv").open(encoding="utf-8-sig", newline="")))
    course_names = {row["course_code"]: row for row in branch_rows}
    course_topics = {}
    branch_topic_meta = {}
    for row in branch_rows:
        course_topics.setdefault(row["course_code"], [name.strip() for name in row.get("topics", "").split("|") if name.strip()])
        for index, name in enumerate(course_topics[row["course_code"]], start=1):
            branch_topic_meta[(row["course_code"], name)] = {
                "topic_id": f"{row['course_code']}_T{index}",
                "difficulty_level": "Beginner" if index <= 2 else "Intermediate",
                "estimated_hours": "3",
            }
    course_names.update(catalog)
    pairs = {}
    for question in questions:
        code, title = question.get("course_id", "").strip(), question.get("question_topic", "").strip()
        if code and title:
            pairs[(code, title)] = True
    if len(pairs) != 860:
        raise SystemExit(f"Expected the verified 860 course-topic pairs, found {len(pairs)}")
    rows = []
    for serial, (code, topic_name) in enumerate(sorted(pairs), start=1):
        course_row = course_names.get(code, {})
        course = course_row.get("course_name", code)
        category = course_row.get("category", "")
        core_topic = core_by_name.get(topic_name)
        branch_meta = branch_topic_meta.get((code, topic_name), {})
        profile_code = code if code in COURSES else (core_topic["course_code"] if core_topic else None)
        if profile_code:
            domain_name, framing, taxonomy, example, caveat, source_a, source_b = COURSES[profile_code]
            detail = TOPIC_DETAIL[profile_code][int(core_topic["topic_id"].rsplit("T", 1)[1]) - 1] if core_topic and profile_code in TOPIC_DETAIL else "Use a small worked case to trace the inputs, intermediate states, result, and assumptions."
        else:
            framing, taxonomy, example, caveat, source_a, source_b = generic_course_frame(course, topic_name, category)
            domain_name = course
            detail = f"{topic_name} is the focus: define its vocabulary, state the conditions under which its rules apply, and connect the representation to a practical result."
        focus = topic_name.split(" - ", 1)[-1]
        overview = (f"{focus} is a learning topic in {course}. {framing} "
                    f"This guide gives a starting explanation and a way to apply the idea; it is a common curriculum reference, not an institution-specific syllabus. "
                    f"Course topic-pair: {code} / {topic_name}.")
        key_concepts = f"{detail} Begin with the definition and notation; identify inputs, states, constraints, and outputs before applying a rule."
        mechanism = f"{taxonomy}. {detail} Work from the stated assumptions, trace one change at a time, and check that the conclusion follows from the model rather than from a memorized label."
        worked_example = f"Take a small case of {focus.lower()}. {detail} Apply the idea one step at a time, then verify the result against the original constraints."
        uses = f"This concept supports coursework and practical design in {course}. It helps you compare alternatives, explain why a method fits a task, and debug a result by checking each assumption and step."
        self_check = f"Explain {focus.lower()} without notes. Give one example from {course}, name a component or governing rule, state an assumption, and describe a case where your chosen approach would not fit."
        topic_id = branch_meta.get("topic_id") or (core_topic["topic_id"] if core_topic else f"{code}__{serial:03d}")
        rows.append({
            "topic_id": topic_id, "course_code": code, "course_name": course, "category": category,
            "topic_name": topic_name,
            "difficulty_level": core_topic["difficulty_level"] if core_topic else branch_meta.get("difficulty_level", "Curriculum outline"),
            "estimated_hours": core_topic["estimated_hours"] if core_topic else branch_meta.get("estimated_hours", ""),
            "overview": overview, "key_concepts": key_concepts, "components_or_types": f"{detail} Related course toolkit: {taxonomy}.",
            "how_it_works": mechanism, "worked_example": worked_example,
            "uses_and_benefits": uses, "tradeoffs_and_common_mistakes": caveat,
            "self_check": self_check,
            "reference_1": source_a or article_search(f"{course} {topic_name}"),
            "reference_2": source_b or gfg_search(f"{course} {topic_name}"),
            "further_reading_search": article_search(topic_name),
            "reference_scope": "Further-reading locator; source pages are not copied into this original Nebula draft.",
            "content_status": "Nebula-authored learning draft; instructor and source review pending",
        })
    out = DATA / "topic_concept_guides.csv"
    fields = list(rows[0])
    with out.open("w", encoding="utf-8-sig", newline="") as stream:
        writer = csv.DictWriter(stream, fieldnames=fields, quoting=csv.QUOTE_MINIMAL)
        writer.writeheader()
        writer.writerows(rows)
    print(f"Wrote {len(rows)} course-topic guides for {len({r['course_code'] for r in rows})} courses to {out}")

if __name__ == "__main__":
    build()
